// This is a shopping cart module in plain JavaScript.
// Your task: convert this entire file to TypeScript.
// Rename it to cart.ts and add proper types throughout.
// No `any` allowed!

function createCart() {
  let items = [];

  return {
    addItem(item) {
      const existing = items.find(i => i.id === item.id);
      if (existing) {
        existing.quantity += item.quantity;
      } else {
        items.push({ ...item });
      }
    },

    removeItem(id) {
      items = items.filter(i => i.id !== id);
    },

    getTotal() {
      return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    },

    getItems() {
      return [...items];
    },

    clear() {
      items = [];
    }
  };
}

// Usage (should still work after your TypeScript conversion):
const cart = createCart();
cart.addItem({ id: 1, name: "Apple", price: 0.99, quantity: 3 });
cart.addItem({ id: 2, name: "Bread", price: 2.49, quantity: 1 });
cart.addItem({ id: 1, name: "Apple", price: 0.99, quantity: 2 }); // adds to existing
console.log(cart.getItems());
console.log("Total: $" + cart.getTotal().toFixed(2));

