export default function App() {
  // Test useLocalStorage
  const [theme, setTheme] = useLocalStorage<'light' | 'dark'>('theme', 'light');

  // Test useDebounce
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebounce(search, 500);

  // Test useFetch
  const { data, loading, error } = useFetch<{ name: string }[]>(
    'https://api.github.com/users/octocat/repos?per_page=5'
  );

  return (
    <div style={{ padding: 24, fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: 32 }}>
      <h1>Custom Hooks</h1>

      <section>
        <h2>useLocalStorage</h2>
        <p>Current theme: <strong>{theme}</strong></p>
        <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')}>
          Toggle Theme
        </button>
        <p><em>Refresh the page — theme should persist!</em></p>
      </section>

      <section>
        <h2>useDebounce</h2>
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Type to search..." />
        <p>Immediate: {search}</p>
        <p>Debounced (500ms): {debouncedSearch}</p>
      </section>

      <section>
        <h2>useFetch</h2>
        {loading && <p>Loading...</p>}
        {error && <p style={{ color: 'red' }}>Error: {error.message}</p>}
        {data && (
          <ul>
            {data.map((repo, i) => <li key={i}>{repo.name}</li>)}
          </ul>
        )}
      </section>
    </div>
  );
}

