// This component has many code smells. Identify them and refactor!
import { useState, useEffect } from 'react';

export default function MessyDashboard({ userId }: { userId: string }) {
  const [userData, setUserData] = useState<any>(null);
  const [userPosts, setUserPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<'profile' | 'posts' | 'settings'>('profile');
  const [editMode, setEditMode] = useState(false);
  const [formName, setFormName] = useState('');
  const [formBio, setFormBio] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [saveLoading, setSaveLoading] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  useEffect(() => {
    setLoading(true);
    fetch(`https://jsonplaceholder.typicode.com/users/${userId}`)
      .then(r => r.json())
      .then(data => {
        setUserData(data);
        setFormName(data.name);
        setFormEmail(data.email);
        setLoading(false);
      })
      .catch(e => { setError(e.message); setLoading(false); });
  }, [userId]);

  useEffect(() => {
    fetch(`https://jsonplaceholder.typicode.com/posts?userId=${userId}`)
      .then(r => r.json())
      .then(posts => setUserPosts(posts.slice(0, 5)))
      .catch(console.error);
  }, [userId]);

  const handleSave = async () => {
    setSaveLoading(true);
    try {
      const res = await fetch(`https://jsonplaceholder.typicode.com/users/${userId}`, {
        method: 'PUT',
        body: JSON.stringify({ name: formName, email: formEmail }),
        headers: { 'Content-Type': 'application/json' }
      });
      const updated = await res.json();
      setUserData(updated);
      setEditMode(false);
    } catch (e: any) {
      setSaveError(e.message);
    } finally {
      setSaveLoading(false);
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!userData) return null;

  return (
    <div style={{ maxWidth: 600, margin: '0 auto', fontFamily: 'sans-serif', padding: 24 }}>
      <div style={{ display: 'flex', gap: 8, marginBottom: 24 }}>
        {(['profile', 'posts', 'settings'] as const).map(t => (
          <button key={t} onClick={() => setTab(t)} style={{ padding: '8px 16px', background: tab === t ? '#0070f3' : '#eee', color: tab === t ? 'white' : 'black', border: 'none', borderRadius: 4, cursor: 'pointer' }}>
            {t.charAt(0).toUpperCase() + t.slice(1)}
          </button>
        ))}
      </div>

      {tab === 'profile' && (
        <div>
          {!editMode ? (
            <div>
              <h2>{userData.name}</h2>
              <p>{userData.email}</p>
              <p>{userData.phone}</p>
              <button onClick={() => setEditMode(true)}>Edit</button>
            </div>
          ) : (
            <div>
              <input value={formName} onChange={e => setFormName(e.target.value)} />
              <input value={formEmail} onChange={e => setFormEmail(e.target.value)} />
              {saveError && <p style={{ color: 'red' }}>{saveError}</p>}
              <button onClick={handleSave} disabled={saveLoading}>{saveLoading ? 'Saving...' : 'Save'}</button>
              <button onClick={() => setEditMode(false)}>Cancel</button>
            </div>
          )}
        </div>
      )}

      {tab === 'posts' && (
        <div>
          <h2>Posts</h2>
          {userPosts.map((post: any) => (
            <div key={post.id} style={{ marginBottom: 16, padding: 12, border: '1px solid #eee', borderRadius: 8 }}>
              <h3>{post.title}</h3>
              <p>{post.body}</p>
            </div>
          ))}
        </div>
      )}

      {tab === 'settings' && (
        <div>
          <h2>Settings</h2>
          <p>Settings coming soon...</p>
        </div>
      )}
    </div>
  );
}

