// Lesson 19: useMemo and useCallback
// Rule: Only optimize after you measure a real problem.
// These hooks add complexity — use them only when the cost is proven.

import { useState, useMemo, useCallback, memo } from 'react';

// An expensive computation (simulated):
function computeExpensiveStats(numbers: number[]) {
  // Simulate slow computation:
  const start = Date.now();
  while (Date.now() - start < 100) {} // block for 100ms
  return {
    sum: numbers.reduce((a, b) => a + b, 0),
    average: numbers.reduce((a, b) => a + b, 0) / numbers.length,
    max: Math.max(...numbers),
    min: Math.min(...numbers),
  };
}

const NUMBERS = Array.from({ length: 1000 }, (_, i) => i + 1);

export default function App() {
  const [count, setCount] = useState(0);
  const [filter, setFilter] = useState(0);

  // TODO 1: Without useMemo, computeExpensiveStats runs on EVERY render.
  // Add a console.log inside computeExpensiveStats to see this.
  // Then wrap with useMemo — what's the dependency array?
  const stats = computeExpensiveStats(NUMBERS.filter(n => n > filter));

  // TODO 2: handleFilterChange is recreated on every render.
  // Child components that receive it as a prop will also re-render.
  // Wrap it with useCallback.
  const handleFilterChange = (value: number) => setFilter(value);

  return (
    <div style={{ padding: 24, fontFamily: 'sans-serif' }}>
      <h1>Performance Demo</h1>
      <p>Unrelated counter (causes re-render): <button onClick={() => setCount(c => c + 1)}>{count}</button></p>
      <p>Filter numbers greater than: <input type="number" value={filter} onChange={e => handleFilterChange(Number(e.target.value))} /></p>
      <StatsDisplay stats={stats} />
    </div>
  );
}

// TODO 3: Wrap StatsDisplay with React.memo so it only re-renders when stats changes.
const StatsDisplay = memo(function StatsDisplay({ stats }: { stats: ReturnType<typeof computeExpensiveStats> }) {
  console.log('StatsDisplay rendered');
  return (
    <div style={{ background: '#f5f5f5', padding: 16, borderRadius: 8 }}>
      <p>Sum: {stats.sum}</p>
      <p>Average: {stats.average.toFixed(2)}</p>
      <p>Max: {stats.max} | Min: {stats.min}</p>
    </div>
  );
});

// Lesson 20: React.memo and Re-render Behavior
// React re-renders a component when:
//   1. Its state changes
//   2. Its props change
//   3. Its parent re-renders (even if props didn't change!)

import { useState, memo, useCallback } from 'react';

// Add render counters to see when each component renders:
let renderCount = { parent: 0, child: 0, memoChild: 0 };

function ChildWithoutMemo({ onClick }: { onClick: () => void }) {
  renderCount.child++;
  console.log(`ChildWithoutMemo rendered (${renderCount.child} times)`);
  return (
    <button onClick={onClick} style={{ padding: '8px 16px', marginRight: 8 }}>
      Child (no memo) — rendered {renderCount.child}x
    </button>
  );
}

// TODO: Wrap this component with React.memo
function ChildWithMemo({ onClick }: { onClick: () => void }) {
  renderCount.memoChild++;
  console.log(`ChildWithMemo rendered (${renderCount.memoChild} times)`);
  return (
    <button onClick={onClick} style={{ padding: '8px 16px', background: '#0070f3', color: 'white' }}>
      Memo Child — rendered {renderCount.memoChild}x
    </button>
  );
}

export default function App() {
  renderCount.parent++;
  const [parentCount, setParentCount] = useState(0);
  const [childMessage, setChildMessage] = useState('');

