// Wire up the mock API to the Chat UI
import { useState, useEffect } from 'react';
import { mockApi } from './api/mockApi';
import type { SendMessageResponse } from './api/contract';

export default function App() {
  const [messages, setMessages] = useState<SendMessageResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [input, setInput] = useState('');

  const CONVERSATION_ID = 'conv-1';
  const CURRENT_USER_ID = 'user-1';

  useEffect(() => {
    mockApi.getMessages(CONVERSATION_ID)
      .then(res => { setMessages(res.messages); setLoading(false); })
      .catch(e => { setError(e.message); setLoading(false); });
  }, []);

  const handleSend = async () => {
    if (!input.trim()) return;
    const content = input.trim();
    setInput('');
    try {
      const msg = await mockApi.sendMessage({ conversationId: CONVERSATION_ID, content, senderId: CURRENT_USER_ID });
      setMessages(prev => [...prev, msg]);
    } catch (e: unknown) {
      if (e instanceof Error) setError(e.message);
    }
  };

  return (
    <div style={{ maxWidth: 500, margin: '0 auto', padding: 24, fontFamily: 'sans-serif' }}>
      <h1>Chat (Mocked API)</h1>
      {loading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>{error} <button onClick={() => setError(null)}>Dismiss</button></p>}
      <div style={{ height: 300, overflowY: 'auto', border: '1px solid #ddd', borderRadius: 8, padding: 12, marginBottom: 12 }}>
        {messages.map(m => (
          <div key={m.id} style={{ textAlign: m.senderId === CURRENT_USER_ID ? 'right' : 'left', marginBottom: 8 }}>
            <span style={{ background: m.senderId === CURRENT_USER_ID ? '#0070f3' : '#f0f0f0', color: m.senderId === CURRENT_USER_ID ? 'white' : 'black', borderRadius: 12, padding: '6px 12px', display: 'inline-block' }}>
              {m.content}
            </span>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex', gap: 8 }}>
        <input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()} style={{ flex: 1, padding: 8, border: '1px solid #ddd', borderRadius: 6 }} placeholder="Type a message..." />
        <button onClick={handleSend} style={{ padding: '8px 16px', background: '#0070f3', color: 'white', border: 'none', borderRadius: 6 }}>Send</button>
      </div>
    </div>
  );
}

// Simple utility functions — easy to start testing with.

export function formatPrice(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength - 3) + '...';
}

export function capitalize(text: string): string {
  if (!text) return '';
  return text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();
}

export function pluralize(count: number, singular: string, plural?: string): string {
  return count === 1 ? `${count} ${singular}` : `${count} ${plural ?? singular + 's'}`;
}

